public interface MethodStep { UrlStep method(String method); }
public interface UrlStep    { FinalStep url(String url); }     // no build() yet
public interface FinalStep  { FinalStep header(String k, String v); HttpRequest build(); }

final class Steps implements MethodStep, UrlStep, FinalStep {
    private String method, url;
    public UrlStep  method(String m) { method = m; return this; }   // return type is the staging
    public FinalStep url(String u)   { url = u;    return this; }
    public FinalStep header(String k, String v) { /* collect */ return this; }
    public HttpRequest build()       { return new HttpRequest(method, url); }
}
